import {CHARACTERS,STAMPS,JOURNALS,SHOP_CATEGORIES} from './wardrobe.js';
import {OverviewMap} from './overview-map.js';
import {PLACES,SHOP,REGIONS} from './content.js';
import {distance,STORAGE_KEY,freshState,sanitizeState,discover,answer,purchase,rankFor,quizCoins} from './core.js';
import {setupPlaceSearch} from './search.js';
import {World} from './world.js';
import {Narrator,GameAudio,koreanVoices} from './audio.js';
import {canVisit} from './geography.js';
import {RELEASE} from './release.js?v=1.3.5';
import {DialogPages,setupViewport,fitPlaceDialog} from './layout.js?v=1.3.5';
import {setupResponsiveHud} from './mobile-ui.js';
import {ensureQuests,activeQuest,selectQuest,recordQuestVisit,questCompleted,DIRECT_BONUS,dayKey} from './quests.js';
import {SYMBOLS,symbolHtml,symbolKey} from './place-icons.js';

const $=s=>document.querySelector(s);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ICONS={
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',
 book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',
 bus:'<rect x="4" y="3" width="16" height="16" rx="4"/><path d="M4 11h16M8 19v2m8-2v2M8 15h1m6 0h1M9 6h6"/>',
 bag:'<path d="M5 8h14l1 13H4L5 8Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',
 qr:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h2v2h4v4h-6zm6-3v3M12 3v3m0 6h3M3 12h3m6 6v3"/>',
 sound:'<path d="m3 9 4 0 5-4v14l-5-4H3V9Zm13-1c2 2 2 6 0 8m3-11c4 4 4 10 0 14"/>',
 mute:'<path d="m3 9 4 0 5-4v14l-5-4H3V9Zm13 0 6 6m0-6-6 6"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2m0 3h.01"/>'
};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[k]}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
$('#help-button').innerHTML=icon('help');

const regionCache=new Map();let changingRegion=false,overviewMap=null,shopCategory='character';
let state=freshState(),storageAvailable=true,world,credits={assets:[]},currentPlace=null,pageIndex=0,toastTimer,panelKind='',journalFilter='all',dialogReward=null,missionReward=null;
try{state=sanitizeState(JSON.parse(localStorage.getItem(STORAGE_KEY)));localStorage.setItem('hs-storage-test','1');localStorage.removeItem('hs-storage-test');}catch{storageAvailable=false;}
const panel=$('#panel-dialog'),placeDialog=$('#place-dialog'),searchDialog=$('#search-dialog');
const sound=new GameAudio(()=>state,toast);let narrator;
narrator=new Narrator(()=>state,()=>{if(!narrator)return;const label=$('#voice-status');if(label)label.textContent=narrator.label;const button=$('#read-aloud');if(button)button.textContent=narrator.speaking?'■ 읽기 멈추기':'▷ 설명 읽어 주기';if(panelKind==='help'&&panel.open)populateVoices();},toast);
const panelPages=new DialogPages(panel,$('#panel-content'),()=>narrator.cancel());
const responsiveHud=setupResponsiveHud({onLayout:()=>world?.resize(),stopInput:()=>{world?.keys.clear();if(world)world.joy=[0,0];const knob=$('#joystick-knob');if(knob)knob.style.transform='';}});
const syncViewport=setupViewport(()=>{responsiveHud.refresh();panelPages.schedule();world?.resize();requestAnimationFrame(()=>fitPlaceDialog(placeDialog));});
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function save(){if(world&&world.state===state){state.position=[...world.position];state.region=world.region;state.locations[world.region]=world.voyage?[world.origin[0]+world.voyage.start[0]/world.mLon,world.origin[1]-world.voyage.start[1]/world.mLat]:world.geoPosition();}try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}$('#save-status').innerHTML=`<span class="live-dot"></span>${storageAvailable?'이 기기에 자동 저장':'이번 실행에서만 저장'}`;}
function update(){
 document.querySelectorAll('[data-travel-speed]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.travelSpeed===(state.travelSpeed||'walk'))));
 $('#coins').textContent=state.coins.toLocaleString('ko-KR');$('#rank').textContent='';
 const region=REGIONS.find(r=>r.id===(world?.region||state.region))||REGIONS[0];const local=PLACES.filter(p=>!p.remote&&(p.region||'naepo')===region.id);const count=local.filter(p=>state.discovered.includes(p.id)).length,total=local.length;
 $('#discovery-count').textContent=count;$('#total-count').textContent=total;$('#discovery-progress').style.width=`${count/total*100}%`;
 $('#journal-badge').textContent=state.discovered.length;$('#journal-badge').hidden=!state.discovered.length;
 document.body.dataset.journal=state.equipped.journal;document.body.style.setProperty('--journal-color',JOURNALS[state.equipped.journal]||'#d8cdb0');document.body.dataset.stamp=state.equipped.stamp;document.body.classList.toggle('reduce-motion',!state.motion);
 const next=PLACES.find(p=>p.id===activeQuest(state));
 $('#quest-heading').textContent=state.dailyQuests?.targets[0]===next?.id?'오늘의 첫 탐방':'오늘의 탐방 미션';
 $('#quest-title').textContent=next?next.name+' 찾아가기':'오늘의 미션을 완성했어요!';
 $('#quest-detail').textContent=next?(state.dailyQuests?.direct?`다른 장소 안내를 열지 않고 도착하면 +${DIRECT_BONUS}금화!`:'다른 곳에 들렀어도 괜찮아요. 목표를 찾아 미션을 마쳐요.'):'새 미션을 받아 모험을 이어가요.';
 $('#quest-route').innerHTML=next?'미션 장소로 출발 <span>↗</span>':'새 미션 받기 <span>↗</span>';
 $('#region-button').innerHTML='<span class=region-long>홍성군 </span>전체 지도';$('.area-pill>span:nth-child(2)').textContent='홍성군';$('.collection>span').textContent='우리 고장 발견 수첩';$('.quest-intro').textContent='내포부터 바닷가까지, 하나로 이어진 모험';$('#world').setAttribute('aria-label','홍성군 전체 탐방 지도');
 $('#sound-button').innerHTML=icon(state.sound?'sound':'mute');$('#sound-button').setAttribute('aria-label',state.sound?'소리 끄기':'소리 켜기');$('#sound-button').title=state.sound?'소리 끄기':'소리 켜기';
 save();
}
function closeDialogs(){overviewMap?.destroy();overviewMap=null;if(searchDialog.open)searchDialog.close();if(panel.open)panel.close();if(placeDialog.open)placeDialog.close();narrator.cancel();world?.keys.clear();if(world){world.joy=[0,0];world.canvas.focus({preventScroll:true});}}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeDialogs);
for(const d of [panel,placeDialog]){d.addEventListener('close',()=>{narrator.cancel();if(d===panel){overviewMap?.destroy();overviewMap=null;}world?.focusMap();});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();});}
function openPanel(kind,title,eyebrow,html,layout='pages'){closeDialogs();panelKind=kind;panelPages.setMode(layout);$('#panel-title').textContent=title;$('#panel-eyebrow').textContent=eyebrow;$('#panel-content').innerHTML=html;panel.showModal();panelPages.reset();}
function tag(p){return`<span class="tag ${p.county!=='홍성군'?'yesan':p.type}">${symbolHtml(p)}${escape(p.area)} · ${SYMBOLS[symbolKey(p)].label}</span>`;}
function creditHtml(p){if(p.mediaType==='map')return '<span>실제 지형 자료를 색과 명암으로 표현한 지도 · OpenStreetMap 기여자 (ODbL) · Terrain Tiles / Mapzen · USGS / NOAA</span>';const c=credits.assets.find(a=>a.id===p.photo);return c?`<span>${escape(c.attribution)} · <a href="${c.sourcePage}" target="_blank" rel="noopener">사진 원문</a> · <a href="${c.licenseUrl}" target="_blank" rel="noopener">이용 조건</a><br>웹용 크기 축소·WebP 변환, 원본 워터마크 유지.</span>`:'<span>이해를 돕는 AI 삽화 · 실제 건물이나 행사 현장 사진이 아닙니다.</span>';}

function visit(p,physical=false){if(!p)return;closeDialogs();$('#welcome').hidden=true;currentPlace=p;pageIndex=0;missionReward=recordQuestVisit(state,p.id,physical);dialogReward=discover(state,p.id);if(dialogReward||missionReward?.bonus)sound.chime();else sound.play('arrival');update();renderPlace();placeDialog.showModal();requestAnimationFrame(()=>fitPlaceDialog(placeDialog));}

function hero(p){return`<div class="place-hero"><img src="./${p.image}" alt="${escape(p.caption)}"><span class="photo-caption">${p.photo?'실제 사진':p.mediaType==='map'?'실제 지형 자료':'이해를 돕는 삽화'} · ${escape(p.caption)}</span><div class="place-hero-info">${tag(p)}<h2>${escape(p.name)}</h2><p>${escape(p.blurb)}</p></div></div>`;}
function schoolDetails(p){const s=p.schoolStory;if(!s)return '';return `<div class="school-facts">${s.foundedDate?`<span>${escape(s.foundedLabel||'설립일')} ${escape(s.foundedDate)}</span>`:''}${s.anniversaryDate?`<span>개교기념일 ${escape(s.anniversaryDate.slice(5).replace('-','월 '))}일</span>`:''}</div>${s.photo?.caption?`<p class="school-photo-note">사진 원문 안내: ${escape(s.photo.caption)}${s.photo.sourceDate?` · ${escape(s.photo.sourceDate)} 자료`:''}</p>`:''}`;}
function schoolLinks(p){const s=p.schoolStory;if(!s)return '';return `<div class="school-links">${s.photo?.sourcePageUrl?`<a class="secondary-button" href="${escape(s.photo.sourcePageUrl)}" target="_blank" rel="noopener">학교 사진 원문 ↗</a>`:''}${s.video?.url?`<a class="secondary-button" href="${escape(s.video.url)}" target="_blank" rel="noopener">${s.video.canUseAsCurrentCampus===false?'옛 교정 영상':'학교 모습 영상'} · ${s.video.year} ↗</a>`:''}${s.officialWebsite?`<a class="secondary-button" href="${escape(s.officialWebsite)}" target="_blank" rel="noopener">학교 누리집 ↗</a>`:''}</div>`;}
function showPlaceSources(p){openPanel('sources',p.name+' · 사진과 자료','장소를 더 알아보기',`${schoolDetails(p)}${schoolLinks(p)}<div class="place-source">${creditHtml(p)}${p.locationNote?`<p><strong>지도 위치 안내</strong><br>${escape(p.locationNote)}</p>`:""}${p.locationSource?`<p><a href="${escape(p.locationSource)}" target="_blank" rel="noopener">좌표 확인 자료 ↗</a></p>`:""}${(p.storySources||[]).map(v=>`<p><a href="${escape(v.url)}" target="_blank" rel="noopener">${escape(v.label)} ↗</a></p>`).join('')}<p><a href="${escape(p.source)}" target="_blank" rel="noopener">장소 자료 원문 ↗</a></p></div><button class="primary-button" id="back-to-story">이야기로 돌아가기</button>`);$('#back-to-story').onclick=()=>{closeDialogs();renderPlace();placeDialog.showModal();requestAnimationFrame(()=>fitPlaceDialog(placeDialog));};}
function renderPlace(){requestAnimationFrame(()=>fitPlaceDialog(placeDialog));const p=currentPlace;placeDialog.dataset.view='story';$('#place-content').innerHTML=`<div class="dialogue-area"><div class="teacher-stage"><img src="./assets/guide.webp" alt="길잡이 다정 선생님"></div><div class="speaker-heading"><span class="speaker-tag">길잡이 · 다정 선생님</span><span class="story-number">${pageIndex+1} / ${p.pages.length}</span></div><div class="speech" tabindex="0" role="region" aria-label="장소 설명">${p.pages[pageIndex]}</div><p class="reward-label">${missionReward?missionReward.bonus?'직행 미션 성공! +'+missionReward.bonus+'금화':'탐방 미션 완료!':dialogReward?`새로운 발견! +${p.coins}금화`:'발견 수첩에 기록된 장소'}</p><div class="dialogue-controls"><button class="secondary-button" id="previous-story" ${pageIndex===0?'disabled':''}>← 이전</button><button class="primary-button" id="next-page">${pageIndex<p.pages.length-1?'다음 이야기 →':'발견 퀴즈 →'}</button></div><div class="story-tools">${'speechSynthesis'in window?'<button class="secondary-button" id="read-aloud">▷ 설명 읽기</button>':''}<button class="secondary-button" id="place-sources">${p.schoolStory?'학교 사진·자료':'사진·자료 출처'}</button><span id="voice-status"></span></div></div>`+hero(p);
 $('#previous-story').onclick=()=>{narrator.cancel();pageIndex=Math.max(0,pageIndex-1);renderPlace();};$('#next-page').onclick=()=>{narrator.cancel();if(pageIndex<p.pages.length-1){pageIndex++;renderPlace();}else renderQuiz();};$('#place-sources').onclick=()=>showPlaceSources(p);
 if($('#read-aloud')){$('#voice-status').textContent=narrator.label;$('#read-aloud').onclick=()=>{if(narrator.speaking)narrator.cancel();else narrator.speak($('.speech').textContent);};}
}

function renderQuiz(){requestAnimationFrame(()=>fitPlaceDialog(placeDialog));placeDialog.dataset.view='quiz';const p=currentPlace;$('#place-content').innerHTML=hero(p)+`<div class="quiz-wrap"><span class="eyebrow">DISCOVERY QUIZ · ${state.solved.includes(p.id)?'복습':'보너스 '+quizCoins(p)+' 금화'}</span><h3>${p.quiz.question}</h3><div class="quiz-options">${p.quiz.options.map((text,i)=>`<button class="quiz-option" data-answer="${i}"><b>${i+1}</b>${text}</button>`).join('')}</div><div id="quiz-feedback" class="quiz-feedback" hidden></div><div class="bottom-actions"><button class="secondary-button" id="reread">이야기 다시 보기</button><button class="secondary-button" id="later">나중에 풀기</button></div></div>`;
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const result=answer(state,p.id,Number(b.dataset.answer));const feedback=$('#quiz-feedback');feedback.hidden=false;requestAnimationFrame(()=>fitPlaceDialog(placeDialog));
  if(!result.correct){sound.play('retry');b.classList.add('wrong');feedback.textContent='괜찮아, 다시 생각해 보자! '+p.quiz.hint;return;}
  b.classList.add('correct');document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);feedback.textContent=p.quiz.explain;update();sound.play('correct');
  $('.quiz-wrap .bottom-actions').innerHTML='<button class="primary-button" id="quiz-finish">수첩에 정리하기 →</button>';$('#quiz-finish').onclick=()=>renderReward(result);
 });$('#reread').onclick=()=>{pageIndex=0;renderPlace();};$('#later').onclick=closeDialogs;placeDialog.scrollTop=0;
}
function renderReward(result){placeDialog.dataset.view='reward';const p=currentPlace;const coins=(dialogReward?.coins||0)+(result.coins||0)+(missionReward?.bonus||0),xp=(dialogReward?.xp||0)+(result.xp||0);$('#place-content').innerHTML=`<div class="reward-panel"><span class="large-spark">✦</span><span class="eyebrow">A NEW PAGE IN YOUR JOURNAL</span><h3>${coins?'우리 고장을 한 걸음 더 알아냈어요!':'이야기를 다시 떠올렸어요!'}</h3><p><strong>${escape(p.name)}</strong>의 이야기가 발견 수첩에 차곡차곡 쌓였어요.<br>${state.solved.length===PLACES.length?'모든 퀴즈를 풀었어요. 이제 너만의 고장 이야기를 들려줘!':'다음 장소에는 어떤 이야기가 기다리고 있을까요?'}</p>${missionReward?`<p class="mission-reward">${missionReward.bonus?'직행 미션 성공! +'+missionReward.bonus+'금화':'탐방 미션 완료!'}</p>`:''}<div class="reward-numbers"><div><strong>+${coins}</strong><small>금화</small></div><div><strong>+${xp}</strong><small>탐험 점수</small></div></div><p>${coins?'같은 장소와 퀴즈의 보상은 처음 한 번만 받아요.':'복습에는 추가 보상이 없어요.'}</p><div class="bottom-actions" style="justify-content:center"><button class="secondary-button" id="reward-journal">발견 수첩 보기</button><button class="primary-button" id="continue-walk">계속 탐방하기 →</button></div></div>`;sound.play('coin');dialogReward=null;missionReward=null;$('#reward-journal').onclick=showJournal;$('#continue-walk').onclick=closeDialogs;}

function showJournal(filter=journalFilter){if(typeof filter!=='string')filter='all';journalFilter=filter;let places=PLACES;if(filter==='found')places=places.filter(p=>state.discovered.includes(p.id));if(filter==='heritage')places=places.filter(p=>['heritage','intangible'].includes(p.type));if(filter==='daily')places=places.filter(p=>['daily','public'].includes(p.type));
 openPanel('journal','나의 발견 수첩','MY DISCOVERY JOURNAL',`<p class="panel-lead">알고 있던 장소도 자세히 보면 새로워요. 오늘의 발견을 모아 우리 고장을 소개해 보세요.</p><div class="stat-row"><div class="stat-box"><small>발견한 장소</small><strong>${state.discovered.length}<span>/ ${PLACES.length}곳</span></strong></div><div class="stat-box"><small>풀어 본 퀴즈</small><strong>${state.solved.length}<span>/ ${PLACES.length}개</span></strong></div><div class="stat-box"><small>탐험 점수</small><strong>${state.xp}<span>점</span></strong></div></div><div class="filters">${[['all','모든 장소'],['found','발견한 장소'],['heritage','우리 고장 문화'],['daily','생활 속 장소']].map(([id,n])=>`<button class="filter-button ${id===filter?'active':''}" data-filter="${id}">${n}</button>`).join('')}</div><div class="journal-grid">${places.map(p=>{const found=state.discovered.includes(p.id);return`<button class="journal-card ${found?'':'locked'}" data-place="${p.id}"><img src="./${p.image}" alt="${escape(p.caption)}" loading="lazy">${found?`<span class="check-stamp">${STAMPS[state.equipped.stamp]||'✓'} ${state.solved.includes(p.id)?'이야기 완성':'발견 완료'}</span>`:''}<div class="card-body">${tag(p)}<h3>${escape(p.name)}</h3><p>${found?escape(p.blurb):p.remote?'홍성 이야기 여행에서 만나기':'지도에서 이 장소 찾아가기'}</p></div></button>`;}).join('')||'<div class="empty-note">아직 발견한 장소가 없어요. 충남도서관부터 찾아가 볼까요?</div>'}</div><div class="journal-note"><label for="my-note">친구에게 소개하고 싶은 장소와 그 까닭은?</label><textarea id="my-note" maxlength="1000" placeholder="예: 나는 홍예공원을 소개하고 싶어. 가족과 함께 산책한 기억이 있거든.">${escape(state.note)}</textarea><small>이 기기에만 저장돼요. 이름이나 연락처를 적지 않아도 돼요.</small></div><div class="bottom-actions"><button class="primary-button" id="export-result">탐방 결과 내려받기 ↓</button><button class="secondary-button" id="export-save">이어하기 파일 저장</button></div>`);
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>showJournal(b.dataset.filter));document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const p=PLACES.find(p=>p.id===b.dataset.place);if(state.discovered.includes(p.id)||p.remote)visit(p);else{goToPlace(p);}});$('#my-note').oninput=e=>{state.note=e.target.value;save();};$('#export-result').onclick=exportResult;$('#export-save').onclick=()=>{download('홍성모험수첩_이어하기.json',JSON.stringify(state,null,2),'application/json');toast('이어하기 파일을 저장했어요.');};
}
function refreshQuests(force=false){if(!world||(!force&&state.dailyQuests?.day===dayKey()))return;const current=world.geoPosition();let candidates=PLACES.filter(p=>!p.remote);if(state.movementMode==='roads'&&state.travelSpeed!=='plane'){const nearby=candidates.map(p=>({p,d:distance(world.position,p.point)})).sort((a,b)=>a.d-b.d).slice(0,60);candidates=nearby.filter(({p,d})=>d>220&&world.navigator.route(world.position,p.point,350)).map(v=>v.p);}ensureQuests(state,candidates,current,Date.now(),Math.random,force);save();}
function launchMission(id){if(!world)return;const p=PLACES.find(p=>p.id===id);if(!p)return;selectQuest(state,id,canVisit(world.position,p));update();goToPlace(p);}
function showMissions(){refreshQuests();const d=state.dailyQuests,targets=d?.targets||[];openPanel('missions','오늘의 탐방 미션','매일 새롭게 만나는 우리 고장',`<p class="panel-lead">첫 탐방과 미션은 무작위로 골라요. 출발한 뒤 다른 장소 안내를 열지 않고 목표에 도착하면 <strong>직행 보너스 ${DIRECT_BONUS}금화</strong>! 길을 지나가거나 NPC에게 도움을 묻는 것은 괜찮아요.</p><div class="mission-list">${targets.map((id,i)=>{const p=PLACES.find(p=>p.id===id),done=questCompleted(state,id),active=activeQuest(state)===id;return `<article class="mission ${done?'complete':''}"><span class="mission-number">${done?'✓':i+1}</span><div><small>${i===0?'오늘의 첫 탐방':'고장 탐방 미션'} · ${active?'진행 중':done?'완료':'선택 가능'}</small><h3>${escape(p.name)}</h3><p>${escape(p.area)} · ${escape(p.blurb)}</p><button class="${done?'secondary':'primary'}-button" data-mission="${id}" ${done?'disabled':''}>${done?'미션 완료':active?'목표로 출발':'이 미션으로 출발'}</button></div></article>`;}).join('')}</div><p class="illustration-note">미션 도착은 직접 이동했을 때 기록해요. 수첩에서 이야기를 다시 읽는 것은 도착으로 세지 않아요. 미션별 보너스는 하루 한 번이에요.</p>${targets.every(id=>questCompleted(state,id))?'<button class="primary-button" id="new-missions">새 미션 받기</button>':''}`);document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>launchMission(b.dataset.mission));if($('#new-missions'))$('#new-missions').onclick=()=>{refreshQuests(true);update();showMissions();};}

function showFerry(){openPanel('ferry','죽도로 떠나는 배 여행','남당항 ↔ 죽도',`<p class="panel-lead">죽도는 바다로 둘러싸인 섬이에요. 남당항에서 배를 타고 찾아가 볼까요?</p><p>버튼을 누르면 남당항까지 이동한 뒤 배를 타요. 돌아올 때는 지도에 나타나는 ‘배 타고 남당항으로’를 누르세요.</p><p>게임에서는 기다리는 시간과 요금을 생략했어요. 바다 위 이동은 간단한 연출이며 실제 항로 안내가 아니에요.</p><button class="primary-button" id="board-ferry">남당항으로 가서 배 타기</button>`);$('#board-ferry').onclick=()=>{closeDialogs();world?.boardFerry(false);};}
function goToPlace(p){closeDialogs();if(p.remote){visit(p);return;}if(!world){toast('지도를 준비하고 있어요.');return;}world.navigate(p.id);}
const PLACE_FILTERS=[['all','전체'],['government','관공서'],['post','우체국'],['bank','은행'],['school','초·중·고·대학교'],['mart','마트'],['shop','일상 가게'],['heritage','역사 유적'],['museum','박물관·미술관'],['festival','축제·행사'],['market','시장'],['specialty','특산물·먹거리'],['cafe','카페'],['nature','공원·자연'],['mapStories','관광지도 이야기']];
function showNearby(only,filter='all',district=''){
 const fixed=Array.isArray(only),all=(fixed?only:PLACES.filter(p=>!p.remote||filter==='mapStories')).filter(p=>!district||p.area===district);let list=all.filter(p=>{const k=symbolKey(p);return filter==='all'||filter==='mapStories'&&p.fromTouristMap||k===filter||filter==='school'&&['elementary','middle','high','university'].includes(k)||filter==='shop'&&p.type==='daily'&&k!=='mart'&&k!=='bank'||filter==='nature'&&p.type==='nature'||filter==='heritage'&&p.type==='heritage'&&!['museum','gallery'].includes(k)||filter==='museum'&&['museum','gallery'].includes(k)||filter==='specialty'&&['specialty','food'].includes(k);});
 if(world)list.sort((a,b)=>(a.point?distance(world.position,a.point):Infinity)-(b.point?distance(world.position,b.point):Infinity));
 openPanel('nearby',fixed?'가까이 있는 장소':district||'홍성의 장소 찾기','FIND A PLACE',`<p class="panel-lead">가까운 장소부터 보여요. 장소를 고르면 지금 위치에서 이동해요. 원에 들어가면 안내가 열려요. ‘관광지도 이야기’에는 위치를 더 확인하고 있는 장소도 있어요.</p>${fixed?'':`<div class="filters">${PLACE_FILTERS.map(([k,v])=>`<button class="filter-button ${filter===k?'active':''}" data-near-filter="${k}">${v}</button>`).join('')}</div><label class="county-search"><input id="nearby-search" type="search" placeholder="장소·축제·먹거리 이름 찾기" aria-label="장소 이름 검색"></label>`}<div class="place-list" id="place-list-results"></div>`);
 const render=q=>{const found=list.filter(p=>!q||(p.name+' '+(p.originalName||'')+' '+p.area+' '+p.category).toLowerCase().includes(q.toLowerCase()));$('#place-list-results').innerHTML=found.map(p=>{const d=world&&p.point?distance(world.position,p.point):0;return`<div class="place-list-row">${symbolHtml(p)}<div><span class="tag ${p.county!=='홍성군'?'yesan':''}">${escape(p.category)} · ${escape(p.area)}</span><h3>${escape(p.name)} ${state.discovered.includes(p.id)?'✓':''}</h3><p>${escape(p.address||p.area)}<br>${p.remote?'이야기로 만나기 · 좌표 확인 중':(d>=1000?(d/1000).toFixed(1)+' km':Math.round(d)+' m')+' 거리'} · 발견 +${p.coins}금화</p></div><button class="primary-button" data-go="${p.id}">${p.remote?'이야기 보기':world&&canVisit(world.position,p)?'안내 보기':'찾아가기'} →</button></div>`;}).join('')||'<p class="empty-note">이름이나 장소 종류를 바꾸어 찾아보세요.</p>';document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>goToPlace(PLACES.find(p=>p.id===b.dataset.go)));};render('');
 if($('#nearby-search'))$('#nearby-search').oninput=e=>render(e.target.value.trim());document.querySelectorAll('[data-near-filter]').forEach(b=>b.onclick=()=>showNearby(null,b.dataset.nearFilter,district));
}
panel.addEventListener('close',()=>{if(!panel.open){overviewMap?.destroy();overviewMap=null;}});
function showTravel(){if(!world){toast('지도를 준비하고 있어요.');return;}const districts=world.data.districts.filter(d=>d.county==='홍성군');
 openPanel('travel','홍성군 전체 지도','현재 위치 · '+world.address,`<div class="travel-layout"><section class="travel-map"><div class="overview-toolbar"><button id="overview-out" aria-label="전체 지도 축소">−</button><span id="overview-zoom-label">100%</span><button id="overview-in" aria-label="전체 지도 확대">+</button><button id="overview-reset">전체 보기</button></div><div class="county-overview"><canvas id="county-overview" width="1000" height="700" aria-label="홍성군 전체 지도. 확대하거나 끌어서 둘러볼 수 있어요."></canvas></div><p class="county-overview-note">주황색 점이 나예요. 두 손가락으로 확대하고 지도를 끌어 보세요.</p></section><section class="travel-regions"><h3>지역 목록</h3><div class="county-districts"><button class="active" data-county-district="">전체 지역</button>${districts.map(d=>`<button data-county-district="${escape(d.county+' '+d.name)}">${escape(d.name)} · ${PLACES.filter(p=>p.area===d.county+' '+d.name&&!p.remote).length}곳</button>`).join('')}</div></section></div><section class="county-results"><h3 id="county-results-heading">전체 지역의 장소</h3><div class="place-list" id="county-place-results"></div></section><details class="county-legend"><summary>장소 아이콘 알아보기</summary><div class="map-legend">${[...new Set(PLACES.map(symbolKey))].map(k=>`<span>${symbolHtml({symbol:k})}${SYMBOLS[k].label}</span>`).join('')}</div></details>${PLACES.some(p=>p.remote)?`<details class="county-stories"><summary>우리 고장의 문화 이야기</summary><div class="travel-grid">${PLACES.filter(p=>p.remote).map(p=>`<article class="travel-card"><img src="./${p.image}" alt="${escape(p.caption)}"><div class="travel-card-body">${tag(p)}<h3>${escape(p.name)}</h3><p>${escape(p.blurb)}</p><button class="primary-button" data-travel="${p.id}">이야기 만나기 →</button></div></article>`).join('')}</div></details>`:''}<div class="bottom-actions"><button class="secondary-button" id="county-back">계속 탐방하기</button></div>`,'scroll');
 const canvas=$('#county-overview');overviewMap?.destroy();overviewMap=new OverviewMap(canvas,world,places=>places.length>1?showNearby(places):goToPlace(places[0]));$('#overview-in').onclick=()=>overviewMap.zoomBy(1.5);$('#overview-out').onclick=()=>overviewMap.zoomBy(1/1.5);$('#overview-reset').onclick=()=>overviewMap.reset();
 const fill=(district='')=>{const places=PLACES.filter(p=>!p.remote&&(!district||p.area===district)).sort((a,b)=>distance(world.position,a.point)-distance(world.position,b.point));$('#county-results-heading').textContent=(district||'전체 지역')+' · '+places.length+'곳';$('#county-place-results').innerHTML=places.map(p=>`<button class="county-place-choice" data-county-place="${p.id}">${symbolHtml(p)}<span><strong>${escape(p.name)}</strong><small>${escape(p.area)} · ${escape(p.category)}</small></span><span aria-hidden="true">↗</span></button>`).join('');document.querySelectorAll('[data-county-place]').forEach(b=>b.onclick=()=>goToPlace(PLACES.find(p=>p.id===b.dataset.countyPlace)));};fill();
 document.querySelectorAll('[data-county-district]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-county-district]').forEach(x=>x.classList.toggle('active',x===b));fill(b.dataset.countyDistrict);});document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>visit(PLACES.find(p=>p.id===b.dataset.travel)));$('#county-back').onclick=closeDialogs;
}
function drawCharacterChoices(){for(const c of document.querySelectorAll('[data-character-preview]')){const g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);world?.motionSprites.draw(g,CHARACTERS[c.dataset.characterPreview].mode,'se',0,false,c.width/2,c.height-4,140,state.equipped.outfit);}}
function showShop(category=shopCategory){if(typeof category==='string'&&SHOP_CATEGORIES.some(([id])=>id===category))shopCategory=category;
 const tabs=`<div class="shop-categories" role="group" aria-label="꾸미기 카테고리">${SHOP_CATEGORIES.map(([id,name])=>`<button class="shop-category" data-shop-category="${id}" aria-pressed="${shopCategory===id}">${name}</button>`).join('')}</div>`;
 const content=shopCategory==='character'?`<p class="shop-intro">마음에 드는 캐릭터를 무료로 골라요.</p><div class="character-choices">${Object.entries(CHARACTERS).map(([id,c])=>`<button class="character-choice" data-character="${id}" aria-pressed="${state.character===id}"><canvas width="160" height="150" data-character-preview="${id}" aria-label="${c.name}"></canvas><strong>${c.name}</strong><span>${state.character===id?'선택 중':'선택하기'}</span></button>`).join('')}</div>`:`<div class="shop-catalog">${SHOP.filter(i=>i.slot===shopCategory).map(i=>{const owned=state.owned.includes(i.id),equipped=state.equipped[i.slot]===i.value;return`<article class="shop-product"><span class="item-swatch" style="background:${i.color}">${i.glyph}</span><h3>${i.name}</h3><p>${i.desc}</p><button class="${equipped?'secondary':'primary'}-button" data-buy="${i.id}" ${!owned&&state.coins<i.price?'disabled':''}>${equipped?'착용 해제':owned?'착용하기':'✧ '+i.price}</button></article>`;}).join('')}</div>`;
 openPanel('shop','캐릭터와 꾸미기','탐방 금화 '+state.coins,tabs+content,'catalog');drawCharacterChoices();
 document.querySelectorAll('[data-shop-category]').forEach(b=>b.onclick=()=>showShop(b.dataset.shopCategory));
 document.querySelectorAll('[data-character]').forEach(b=>b.onclick=()=>{state.character=b.dataset.character;update();showShop();sound.play('click');});
 document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const r=purchase(state,b.dataset.buy);if(!r.ok){toast('금화가 조금 더 필요해요.');return;}sound.play(r.bought?'coin':'click');update();showShop();});}

function showNpc(npc,topic='region'){const target=PLACES.find(p=>p.id===activeQuest(state));const text=topic==='help'?'상단에서 걷기, 자전거, 자동차, 슈퍼카, 비행기를 고를 수 있어. 길로만 다니기에서는 길을 따라가고, 길 무시하기에서는 길 밖으로도 다녀. 물 위는 비행기로 이동하고 죽도는 배로 갈 수 있어. 가까운 장소는 E 키나 탐방하기 버튼으로 살펴보렴.':topic==='mission'?(target?`지금 목표는 ${target.name}이야. 다른 장소 안내를 열지 않고 직접 도착하면 직행 보너스 ${DIRECT_BONUS}금화를 받아. 나에게 도움을 묻는 것은 괜찮아!`:'오늘의 미션을 모두 마쳤구나! 새 미션을 받아 또 다른 장소를 만나 보자.'):npc.history+' '+npc.story;
 openPanel('npc',npc.name+' · '+npc.district,'고장의 이웃과 이야기해요',`<div class="npc-dialogue"><canvas id="npc-portrait" width="240" height="250" aria-label="${npc.name} 캐릭터"></canvas><h3>${topic==='help'?'어떻게 탐방할까요?':topic==='mission'?'다음 목적지는 어디일까요?':escape(npc.area)+'의 이야기'}</h3><p class="npc-speech">${escape(text)}</p></div><div class="bottom-actions npc-options"><button class="secondary-button" data-npc-topic="region">지역 이야기</button><button class="secondary-button" data-npc-topic="help">게임 도움</button><button class="secondary-button" data-npc-topic="mission">미션 도움</button></div><div class="bottom-actions"><button class="primary-button" id="npc-next">${target?'미션 장소로 출발':'새 미션 받기'}</button><button class="secondary-button" id="npc-read">▷ 읽어 주기</button></div><p class="illustration-note">게임 속 가상의 길잡이예요. <a href="${npc.source}" target="_blank" rel="noopener">지역 이야기 출처 ↗</a></p>`);
 const c=$('#npc-portrait');c.dataset.sprite=npc.sprite;world.drawNpc(c.getContext('2d'),npc.sprite,120,235,215);document.querySelectorAll('[data-npc-topic]').forEach(b=>b.onclick=()=>showNpc(npc,b.dataset.npcTopic));$('#npc-next').onclick=()=>{if(target)launchMission(target.id);else{refreshQuests(true);update();showMissions();}};$('#npc-read').onclick=()=>narrator.speak(text);
}
$('#npc-talk').onclick=()=>{if(world?.nearNpc)world.interactNpc(world.nearNpc);};
function showAbout(){openPanel('about','홍성 모험 수첩','버전 '+RELEASE.version,`<section class="about-info"><h3>함께 알아가는 우리 고장</h3><dl><dt>제작자</dt><dd>${RELEASE.creator}</dd><dt>소속</dt><dd>${RELEASE.organization}</dd><dt>연락처</dt><dd><a href="mailto:${RELEASE.email}">${RELEASE.email}</a></dd><dt>버전</dt><dd>${RELEASE.version} · ${RELEASE.date}</dd></dl></section><h3>최근 변경점</h3>${RELEASE.changes.map(v=>`<p class="change-item">${v}</p>`).join('')}`);}
$('#about-button').onclick=showAbout;$('.demo-tag').textContent='v'+RELEASE.version;
function showQR(){openPanel('qr','태블릿으로 모험을 이어가요','SCAN & EXPLORE',`<div class="qr-content"><img src="./assets/demo-qr.png" alt="홍성 모험 수첩 데모 접속 QR 코드"><div><h3>카메라로 QR 코드를 비춰 주세요</h3><p>갤럭시 태블릿의 카메라로 스캔한 뒤<br>링크를 누르면 게임이 열려요.</p><p>진행 기록은 <strong>각 기기에 따로 저장</strong>돼요.<br>기기를 옮길 때는 ‘이어하기 파일’을 이용해요.</p><p>현재는 제작자 확인용 비공개 버전이에요.<br>학생 배포에는 사이트의 열람 권한 설정이 필요해요.</p><button class="primary-button" id="copy-link">접속 주소 복사</button><div class="qr-url">https://hongseong-adventure-demo.anyconium.chatgpt.site</div></div></div>`);$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText('https://hongseong-adventure-demo.anyconium.chatgpt.site');toast('접속 주소를 복사했어요.');}catch{toast('아래에 표시된 주소를 길게 눌러 복사해 주세요.');}};}
function populateVoices(){const select=$('#voice-setting');if(!select)return;select.innerHTML='<option value="auto">Google 한국어 우선 (자동)</option>'+koreanVoices(narrator.voices).map(v=>`<option value="${escape(v.voiceURI)}">${escape(v.name)}</option>`).join('');select.value=[...select.options].some(o=>o.value===state.voiceURI)?state.voiceURI:'auto';}
function showHelp(){openPanel('help','탐방 안내와 설정','A GUIDE FOR LITTLE EXPLORERS',`<div class="help-section"><h3>어떻게 탐방하나요?</h3><p>① 장소 원 안에 들어가면 안내가 열려요. 가까이에서 표지나 원을 눌러도 돼요.<br>② 왼쪽 아래 조이스틱 또는 방향키·WASD로 직접 걸어도 좋아요.<br>③ 먼 장소를 누르면 찾아가요. 다시 보고 싶으면 원 밖으로 나갔다 들어오거나 ‘탐방하기’ 또는 E 키를 눌러요.<br>④ 이야기를 읽고 퀴즈를 풀면 금화를 더 받을 수 있어요. 틀리면 힌트를 보고 다시 도전해요.</p><p>홍성군 전체가 하나의 지도로 이어져 있어요. + / − 버튼으로 확대하고, 미니맵에서 내 위치를 확인해요. 상단 메뉴에서 ‘걷기 / 자전거 ×2 / 자동차 ×4 / 슈퍼카 ×8 / 비행기 ×16’을 골라 보세요. ‘길로만 다니기’에서는 클릭과 조이스틱 모두 길을 따라가요. ‘길 무시하기’에서도 바다와 큰 저수지는 피해서 이동해요. 비행기는 길 모드에서도 자유롭게 날아요. 상단 검색창에 장소 이름 일부나 초성을 입력하면 자동완성 목록이 나와요. 자동차의 일방통행 규칙은 적용하지 않아요. 태블릿을 가로로 놓으면 지도를 더 넓게 볼 수 있어요.</p></div><div class="help-section"><h3>설정</h3><div class="setting-row"><label for="speed-setting">이동 속도</label><select id="speed-setting"><option value="0.75" ${state.speed===.75?'selected':''}>천천히</option><option value="1" ${state.speed===1?'selected':''}>보통</option><option value="1.4" ${state.speed===1.4?'selected':''}>빠르게</option></select></div><div class="setting-row"><label for="motion-setting">캐릭터 움직임 효과</label><select id="motion-setting"><option value="on" ${state.motion?'selected':''}>켜기</option><option value="off" ${!state.motion?'selected':''}>줄이기</option></select></div><div class="setting-row"><label for="sfx-setting">효과음</label><select id="sfx-setting"><option value="on" ${state.sound?'selected':''}>켜기</option><option value="off" ${!state.sound?'selected':''}>끄기</option></select></div><div class="setting-row"><label for="music-setting">배경음</label><select id="music-setting"><option value="off" ${!state.music?'selected':''}>끄기</option><option value="on" ${state.music?'selected':''}>켜기</option></select></div><div class="setting-row"><label for="volume-setting">소리 크기</label><input id="volume-setting" type="range" min="0" max="1" step="0.1" value="${state.volume}"></div><div class="setting-row"><label for="voice-setting">설명 읽기 음성</label><select id="voice-setting"></select></div><p class="voice-note">Google 한국어 음성을 먼저 사용해요. 기기와 브라우저에 따라 제공되는 음성이 달라요. Google 음성이 없으면 기기에 있는 한국어 음성을 사용해요.</p><div class="bottom-actions"><button class="secondary-button" id="voice-test">선택한 음성 들어 보기</button></div><div class="bottom-actions"><button class="secondary-button" id="load-save">이어하기 파일 불러오기</button><button class="danger-button" id="reset-progress">이 기기 기록 초기화</button></div><input type="file" id="save-file" accept=".json,application/json" hidden><div id="reset-confirm"></div></div><div class="help-section"><h3>선생님을 위한 안내</h3><p><strong>대상:</strong> 아이스크림 초등 사회 3학년 1학기 1단원 연계 활동용 게임. 장소 경험 떠올리기, 주변 장소의 특징 알아보기, 친구에게 소개하기를 중심으로 구성했어요. 교과서 문장을 옮기지 않고 새로운 설명과 문항을 작성했어요.</p><p>교과서의 정확한 차시·쪽수와 책으로 된 홍성 지역화 교재의 내용은 아직 대조하지 않았어요. 정식 수업용 문항은 교재 검토 후 확정해야 해요.</p><p><strong>구현 범위:</strong> 홍성군의 3읍·8면 전체를 한 지도에서 이동하며 ${PLACES.filter(p=>!p.remote).length}개 장소를 탐방해요. 관공서·학교·가게·역사 유적·박물관·축제·시장·특산물·먹거리·카페·공원·휴양림을 유형별 아이콘으로 표시했어요. 지도에 없는 시설도 있어 전체 시설 명부와 같지는 않아요.</p><p><strong>보상:</strong> 일상 장소 10금화, 공공·자연 장소 40~80금화, 지역 문화유산·무형문화 100금화, 시장·특산물·축제 60~100금화. 첫 발견에만 지급하고 퀴즈 보너스도 한 번만 받아요. 순위 경쟁은 없어요.</p><p><strong>저장:</strong> 이름·계정·GPS 없이 브라우저에 저장해요. 브라우저 데이터 삭제나 시크릿 모드에서는 기록이 사라질 수 있어요. 결과 또는 이어하기 파일을 내려받아 보관할 수 있어요.</p><p><strong>열람:</strong> 현재 사이트는 제작자 확인용 비공개 버전이에요. QR 코드는 접속 주소를 담고 있으며 사이트 열람 권한을 바꾸지는 않아요.</p></div><div class="help-section"><h3>실제 지도와 표현 방식</h3><p>2026년 9월 9일 조회한 <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap 기여자 · ODbL</a>의 홍성군 전역과 인접 지역의 도로·건물·공원·하천·해안선·군 경계를 바탕으로 그렸어요. 지도는 북쪽이 위이며, 도형의 위치와 연결을 유지했어요. 데이터에 없는 건물, 개별 점포와 실제 건물 출입구는 모두 표현하지 못했어요.</p><p>도의회는 <a href="https://council.chungnam.go.kr/kr/locationCnts.do" target="_blank" rel="noopener">공식 주소</a>에 따라 예산군으로 표시했고, 위치는 공개 좌표 자료와 대조했어요. 도청 본관은 홍성군이에요. 점선은 두 군의 경계예요.</p><p>산의 높낮이는 <a href="https://registry.opendata.aws/terrain-tiles/" target="_blank" rel="noopener">Terrain Tiles / Mapzen</a>의 실제 고도 데이터를 색과 명암으로 표현했어요. 한국 지역의 SRTM·GMTED2010 자료는 USGS, ETOPO1 자료는 NOAA 제공이며 <a href="https://github.com/tilezen/joerd/blob/master/docs/attribution.md" target="_blank" rel="noopener">출처와 이용 조건</a>을 확인할 수 있어요. 명암은 산의 모습을 알아보기 쉽게 강조했으며 실측 3D 지형이나 현재 현장 영상은 아니에요.</p><p>일반 가게는 공개된 지점명·주소·지도 좌표를 교차확인했어요. 점포 좌표는 출처의 표시값으로, 건물의 정확한 출입구나 층을 뜻하지 않아요. 특히 노0랜드와 파리0게뜨는 서로 다른 주소이나 출처 지도 좌표가 가까워 정밀 위치 재확인이 필요해요. <a href="./assets/shop-location-sources.json" download>가게 위치 자료와 출처</a></p><p>캐릭터와 표지 크기, 이동 속도는 게임에 맞게 조정했어요. NPC와 나무·꽃·벤치 장식은 게임 표현이며 실제 시설 위치를 나타내지는 않아요. 길 모드는 공개 지도에 연결된 도로와 산책로를 따라가요. 건물 중앙 대신 가까운 길에서 안내가 열릴 수 있어요. 바다와 큰 저수지는 지상 이동으로 건널 수 없어요. 비행기는 물 위를 날 수 있고 죽도는 남당항에서 배를 타고 왕복해요. 이동 경로는 게임용이며 실제 보행 경로나 출입 가능 구역을 안내하지 않아요.</p><p>읍·면 표시는 실제 경계 안에 있는 캐릭터의 좌표로 판정해요. 본 데이터는 <a href="https://sgis.kostat.go.kr" target="_blank" rel="noopener">통계청 통계지리정보서비스(SGIS)</a>에서 공공누리 제1유형으로 개방한 행정동 경계를 가공한 것이며(가공: <a href="https://github.com/vuski/admdongkor/tree/master/ver20260701" target="_blank" rel="noopener">vuski/admdongkor, 2026년 7월 자료</a>), CC BY 4.0으로 배포됩니다. 경계 부근의 오차가 있을 수 있어요.</p><p>학교 이름과 주소는 <a href="https://open.neis.go.kr" target="_blank" rel="noopener">나이스 교육정보 개방 포털</a>의 학교 기본정보와 대조했어요. 시설 좌표는 공개 지도의 등록 위치이며 현재 출입구나 영업 여부를 보증하지 않아요.</p><p><a href="./map-county.json" download>홍성군 지도 자료 (도로·건물: ODbL)</a> · <a href="./county-boundaries.json" download>읍·면 경계 자료 (CC BY 4.0)</a> · <a href="./assets/facility-location-sources.json" download>추가 시설과 확인 출처</a> · <a href="./assets/culture-location-sources.json" download>역사·문화·생활 장소와 확인 출처</a></p></div><div class="help-section"><h3>이번에 추가한 장소</h3><p>농협은행·농협·하나로마트는 원래 이름으로 표시해요. 다른 상호는 가운데를 0으로 가렸고 원래 이름으로도 검색할 수 있어요. 남산휴양림은 남산산림욕장 이름으로, 국립오서산자연휴양림은 보령시 청라면으로 표시해요. 내포 고속시외버스정류소는 예산군 삽교읍이에요.</p><p>철길은 공개 지도에 등록된 장항선·서해선 등의 실제 선형을 그렸어요. 열차 운행 시각이나 개통·영업 여부를 실시간 안내하지는 않아요. 일부 공원과 물놀이장은 공원 대표 위치이며 각 장소의 자료에서 확인할 수 있어요.</p><p><a href="./assets/expansion-location-sources.json" download>추가 장소와 좌표 출처</a></p></div><div class="help-section"><h3>사진과 자료 출처</h3><p>축제는 대표 행사 장소를 표시했으며 상시 개최를 뜻하지 않아요. 특산물·먹거리 표시는 생산·판매 지역을 소개하는 탐방 지점으로, 특정 상점을 추천하거나 물건을 구매하는 기능은 없어요.</p>${credits.assets.map(c=>`<p><strong>${escape(c.place)}</strong><br>${escape(c.attribution)} · <a href="${c.sourcePage}" target="_blank" rel="noopener">원문</a> · <a href="${c.licenseUrl}" target="_blank" rel="noopener">${escape(c.license)}</a><br>${escape(c.changes||'웹용 크기 축소·WebP 변환')}</p>`).join('')}<p>사진이 없는 의회 역할·영화관·결성농요와 추가한 가게에는 이해를 돕는 AI 삽화를 사용했어요. 실제 건물의 외형이나 공연의 정확한 재현을 뜻하지 않아요. 캐릭터와 삽화는 이 게임을 위해 새로 제작했어요.</p><p><a href="https://hongju.or.kr/home/content.do?menu_cd=000098" target="_blank" rel="noopener">홍성문화관광재단 · 홍성 명소</a> · <a href="https://tour.chungnam.go.kr/prog/trsrcn/kor/sub02_01_02/view.do?trsrcnNo=1284" target="_blank" rel="noopener">충남관광 · 결성농요농사박물관</a></p><p>학교마다 설립 연혁과 확인된 특징, 학교 누리집과 사진 원문 링크를 연결했어요. 사용 허락이 확인되지 않은 학교 사진은 복사하지 않고 공통 삽화를 사용했어요.</p><p><a href="./assets/hongseong-tourist-map-2022.jpg" target="_blank" rel="noopener">첨부 관광지도 원본 · 2022년 11월</a> · <a href="./assets/tourist-map-reconciliation.json" download>관광지도 대조 결과</a> · <a href="./assets/school-research.json" download>학교별 확인 자료</a></p><p>글꼴: <a href="https://hangeul.naver.com/font" target="_blank" rel="noopener">네이버 나눔스퀘어라운드</a> · <a href="./assets/NANUM-LICENSE.txt" target="_blank" rel="noopener">SIL Open Font License</a>. 배경음과 효과음은 웹 오디오로 만든 짧은 오리지널 음이며, 결성농요의 실제 노래가 아니에요.</p></div>`);
 populateVoices();$('#voice-setting').onchange=e=>{state.voiceURI=e.target.value;narrator.cancel();save();};$('#voice-test').onclick=()=>narrator.speak('안녕! 우리 고장 홍성의 이야기를 함께 알아보자.');$('#sfx-setting').onchange=e=>{state.sound=e.target.value==='on';if(state.sound)sound.unlock();else sound.stop();update();};$('#music-setting').onchange=e=>{state.music=e.target.value==='on';if(state.music){state.sound=true;$('#sfx-setting').value='on';sound.unlock();}update();};$('#volume-setting').oninput=e=>{state.volume=Number(e.target.value);save();};
 $('#speed-setting').onchange=e=>{state.speed=Number(e.target.value);save();};$('#motion-setting').onchange=e=>{state.motion=e.target.value==='on';update();};$('#load-save').onclick=()=>$('#save-file').click();$('#save-file').onchange=importSave;$('#reset-progress').onclick=()=>{$('#reset-confirm').innerHTML='<p style="font-size:13px;line-height:1.8">발견 기록, 금화와 구입한 꾸미기가 지워져요. 먼저 이어하기 파일을 저장할까요?</p><div class="bottom-actions"><button class="secondary-button" id="backup-first">파일 저장</button><button class="danger-button" id="confirm-reset">기록 지우고 처음부터</button></div>';$('#backup-first').onclick=()=>download('홍성모험수첩_이어하기.json',JSON.stringify(state,null,2),'application/json');$('#confirm-reset').onclick=()=>{state=freshState();save();location.reload();};};
}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportResult(){const text=['홍성 모험 수첩 · 나의 탐방 결과','',`발견: ${state.discovered.length} / ${PLACES.length}곳`, `퀴즈: ${state.solved.length} / ${PLACES.length}개`,`탐험 점수: ${state.xp}점`,`칭호: ${rankFor(state.xp)}`,'','내가 발견한 장소',...PLACES.filter(p=>state.discovered.includes(p.id)).map(p=>`- ${p.name} (${p.area}) · 퀴즈 ${state.solved.includes(p.id)?'완료':'아직'}`),'','친구에게 소개하고 싶은 장소와 까닭',state.note||'(아직 적지 않았어요)','','완료한 미션',...state.questLedger.map(r=>'- '+r.day+' '+(PLACES.find(p=>p.id===r.place)?.name||r.place)+' · 직행 보너스 '+r.bonus+'금화')].join('\n');download('홍성모험수첩_탐방결과.txt','\uFEFF'+text);toast('탐방 결과를 내려받았어요.');}
async function importSave(e){const f=e.target.files[0];if(!f)return;if(f.size>200000){toast('이어하기 파일이 너무 커요. 올바른 JSON 파일을 선택해 주세요.');return;}try{const raw=JSON.parse(await f.text());if(raw.version!==1||!Array.isArray(raw.discovered))throw new Error('invalid');const incoming=sanitizeState(raw);$('#reset-confirm').innerHTML=`<p style="font-size:13px;line-height:1.8">파일에는 ${incoming.discovered.length}곳의 발견 기록이 있어요.<br>현재 기기의 기록을 이 파일로 바꿀까요?</p><div class="bottom-actions"><button class="primary-button" id="confirm-import">이 기록으로 이어하기</button><button class="secondary-button" id="cancel-import">취소</button></div>`;$('#confirm-import').onclick=()=>{state=incoming;save();location.reload();};$('#cancel-import').onclick=()=>{$('#reset-confirm').innerHTML='';};}catch{toast('이어하기 파일을 읽지 못했어요. 이 게임에서 저장한 JSON 파일인지 확인해 주세요.');}}

$('#sound-button').onclick=async()=>{state.sound=!state.sound;if(state.sound){await sound.unlock();sound.play('arrival');toast('효과음을 켰어요. 배경음은 설정에서 따로 켤 수 있어요.');}else{sound.stop();toast('효과음과 배경음을 껐어요.');}update();};
const unlockAudio=()=>{if(state.sound)sound.unlock();};document.addEventListener('pointerdown',unlockAudio,{once:true});document.addEventListener('keydown',unlockAudio,{once:true});
document.addEventListener('click',e=>{if(e.target.closest('button')&&!e.target.closest('#sound-button,[data-answer]'))sound.play('click');});
document.addEventListener('visibilitychange',()=>{if(document.hidden)narrator.cancel();else if(world&&state.dailyQuests?.day!==dayKey()){refreshQuests();update();}});
$('#close-welcome').onclick=()=>{$('#welcome').hidden=true;};
$('#region-button').onclick=showTravel;$('#nearby-button').onclick=()=>showNearby();
$('#journal-button').onclick=()=>showJournal();$('#travel-button').onclick=showTravel;$('#shop-button').onclick=showShop;$('#quests-button').onclick=showMissions;$('#help-button').onclick=showHelp;$('#qr-button').onclick=showQR;$('#walk-button').onclick=()=>{closeDialogs();world?.canvas.focus();toast('장소 표지를 누르거나 조이스틱으로 걸어 보세요.');};
$('#quest-route').onclick=()=>{if(!world)return;const id=activeQuest(state);if(id){$('#welcome').hidden=true;launchMission(id);}else{refreshQuests(true);update();showMissions();}};$('#explore-button').onclick=()=>{if(world?.nearby.length>1)showNearby(world.nearby);else if(world?.nearest)world.openPlace(world.nearest);};
$('.map-credit').innerHTML='지도 © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> · 지형 Terrain Tiles / USGS / NOAA';
$('#ferry-return').onclick=()=>{closeDialogs();world?.boardFerry(true);};
$('#minimap-expand').onclick=showTravel;$('#minimap').onclick=showTravel;

async function start(){update();try{const [m,c]=await Promise.all([fetch('./'+(REGIONS.find(r=>r.id===state.region)||REGIONS[0]).file).then(r=>{if(!r.ok)throw new Error('map');return r.json();}),fetch('./assets/photo-credits.json').then(r=>r.json())]);credits=c;regionCache.set(m.region,m);world=new World($('#map'),m,PLACES,state,{paused:()=>panel.open||placeDialog.open||searchDialog.open||changingRegion,toast,save,step:t=>{if(['walk','bike'].includes(state.travelSpeed))sound.footstep(t);},sound:k=>sound.play(k),choosePlaces:showNearby,ferry:showFerry,voyage:(active,label)=>{const el=$('#voyage-status');el.hidden=!active;el.textContent=label||'';$('#ferry-return').hidden=true;},charactersReady:()=>drawCharacterChoices(),spritesReady:()=>{const c=$('#npc-portrait');if(c&&world)world.drawNpc(c.getContext('2d'),c.dataset.sprite,120,235,215);},npc:showNpc,nearNpc:n=>{$('#npc-talk').hidden=!n;if(n)$('#npc-talk').textContent=n.name+'와 대화 · E';},arrive:(p)=>{if(!placeDialog.open&&!panel.open)visit(p,true);},near:p=>{$('#explore-button').disabled=!p;$('#explore-subtitle').textContent=p?p.name:'장소 가까이에서';$('#arrival-hint').hidden=!p;if(p)$('#arrival-hint').textContent=p.county!=='홍성군'?'여기는 '+p.county+'! 주소도 함께 알아봐요.':`${p.name}에 도착했어요.`;}});$('#map-loading').hidden=true;refreshQuests();update();document.fonts.ready.then(()=>{world.makeBase();world.draw();panelPages.schedule();fitPlaceDialog(placeDialog);});if(!storageAvailable)toast('기록을 저장할 수 없어요. 탐방 뒤 결과 파일을 내려받아 주세요.');if(state.discovered.length)$('#welcome').hidden=true;}
 catch(e){$('#map-loading').innerHTML='<div style="text-align:center;padding:30px">지도를 불러오지 못했어요.<br><small>인터넷 연결을 확인한 뒤 다시 열어 주세요.</small><br><button id="retry-load" class="primary-button" style="margin-top:20px">다시 불러오기</button></div>';$('#retry-load').onclick=()=>location.reload();}}
setupPlaceSearch(PLACES,p=>{searchDialog.close();goToPlace(p);},()=>{if(world){world.keys.clear();world.joy=[0,0];world.route=[];world.routePlace=null;world.routeNpc=null;world.ferryPending=null;}});
start();

$('#search-button').onclick=()=>{closeDialogs();searchDialog.showModal();$('#place-search input').focus();};$('#search-close').onclick=()=>searchDialog.close();searchDialog.addEventListener('close',()=>world?.focusMap());
